------------ LifeCycle ------------
function CatHouseExploreTaskPopup:__init()
    self:CleanField()
end

function CatHouseExploreTaskPopup:__delete()
    self:CleanField()
    self.controller = nil
end

function CatHouseExploreTaskPopup:CleanField()
    self.taskData = nil
    self.listStar = nil
end

function CatHouseExploreTaskPopup:Awake()
    ---@type Engine.UI.UIArgument
    local argument = self.controller.Argument
    local parameters = argument.parameters
    self.taskData = parameters.taskData
    self.exploreId = parameters.exploreId
    self.listStar = {}
    if not IsNull(CatHouseExploreMgr) then
        CatHouseExploreMgr.attributeTypeCurrent = checkNumber(self.taskData.attributeId)
    end
end

function CatHouseExploreTaskPopup:OnFocus(focus)
    local _offsetNaviBar = function(bool)
        local Lua_NaviBarPath = "Game.Main.UINavigatorBar"
        local navigatorBar = GetLuaBehaviour(CS.UINavigationBarRoot.Instance.gameObject, Lua_NaviBarPath)
        local healthNodeBg_AP = navigatorBar.Env.HealthNodeBg.anchoredPosition
        navigatorBar.Env.HealthNodeBg.anchoredPosition = Vector2.New(bool and -160 or 0, healthNodeBg_AP.y)
        --if bool then
        --    navigatorBar.Env:CustomTitleName(checkString(self.taskData.taskName))
        --end
    end
    if focus then
        GameUtils.UpdateNavBarShowGoods({ 300004 }, true)
        _offsetNaviBar(true)
        self:RefreshCatsTeamList()
    else
        _offsetNaviBar(false)
        GameUtils.RestoreHealthNodes()
    end
end

function CatHouseExploreTaskPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.eventAutoFormation = Events.AddListener(Constants.EventNames.CatHouseExploreAutoFormation, Bind(self, self.RefreshCatsTeamList))
        self:SetPanelInfo(self.taskData)
    end))
    return coWait
end

function CatHouseExploreTaskPopup:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        SetButtonAction(self.BtnBack.gameObject, function() 
            UIModule.BackDialog()
        end)
    end))
    return coWait
end

function CatHouseExploreTaskPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.CatHouseExploreAutoFormation, self.eventAutoFormation)
        CatHouseExploreMgr:CleanListCatsTeam()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end
