------------ PanelInfo ------------
function CatHouseExploreTaskPopup:SetPanelInfo(taskData)
    xTry(function()
        self:InitRootTaskStars(checkNumber(taskData.taskQuality))
        self:InitTeamListPanel(taskData)
        self:InitHarvestPanel(taskData)
        if not IsNull(self.ImgBgBlack) then
            self.ImgBgBlack:LoadSprite(taskData.picture)
        end
        self.TextTitle.text = checkString(self.taskData.taskName)
    end)
    print("->CatHouseExploreTaskPopup:SetPanelInfo:", table.dump(checkTable(CatHouseExploreMgr:GetTaskExtraCondition(taskData.taskId))))
end

---任务星级
function CatHouseExploreTaskPopup:InitRootTaskStars(taskQuality)
    for i = 1, checkInt(CatHouseExploreMgr.EXPLORE_TASK_STARS_MAX) do
        local go = KTool.Instantiate(self.StarLevelGroup.gameObject, self.ImgStar.gameObject)
        if not IsNull(go) then
            KTool.SetActive(go, true)
        end
        local imgSwitch = KTool.GetOrAddComponent(go, typeof(UISwitchImage))
        imgSwitch.Status = i <= checkNumber(taskQuality) and 2 or 1
    end
end

function CatHouseExploreTaskPopup:InitTeamListPanel(taskData)
    xTry(function()
        local lbTeamList = self.TeamListPanel
        if not IsNull(lbTeamList) then
            lbTeamList:Init()
            local ltTeamList = lbTeamList.Env
            if ltTeamList then
                ltTeamList:SetPanelInfo(taskData, self.exploreId)
            end
        end
    end)
end

function CatHouseExploreTaskPopup:InitHarvestPanel(taskData)
    xTry(function()
        local lbHarvestList = self.HarvestPanel
        if not IsNull(lbHarvestList) then
            lbHarvestList:Init()
            local ltHarvestList = lbHarvestList.Env
            if ltHarvestList then
                ltHarvestList:SetPanelInfo(taskData, self.exploreId)
            end
        end
    end)
end

function CatHouseExploreTaskPopup:RefreshCatsTeamList()
    local attributeValue = checkNumber(CatHouseExploreMgr:GetCatsListTaskAttributeValue(checkNumber(self.taskData.attributeId)))
    local lbTeamList = self.TeamListPanel
    if not IsNull(lbTeamList) then
        ---@type CatHouseExploreTaskTeamListPanel
        local ltTeamList = lbTeamList.Env
        ltTeamList:RefreshCatTeamList()
        ltTeamList:SetTeamAttributeValue(attributeValue)
    end
    local lbHarvest = self.HarvestPanel
    if not IsNull(lbHarvest) then
        local ltHarvest = lbHarvest.Env
        ltHarvest:RefreshTaskCondition(attributeValue)
    end
end

